#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/stat.h>
#include <errno.h>
#include <limits.h>

#define BUCKET_ROOT "/var/cloud_storage/buckets/"
#define MAX_PATH_LEN 4096
#define AES_KEY_SIZE 32
#define AES_IV_SIZE 16
#define BLOCK_SIZE 16

typedef struct {
    char bucket_id[64];
    unsigned char master_key[AES_KEY_SIZE];
    int encryption_enabled;
} StorageContext;

typedef struct {
    char segments[32][256];
    int num_segments;
} NormalizedPath;

/* Normalize path by resolving each segment */
static int normalize_path_segments(const char *input, NormalizedPath *out) {
    char buf[MAX_PATH_LEN];
    strncpy(buf, input, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    out->num_segments = 0;
    char *token = strtok(buf, "/");

    while (token != NULL && out->num_segments < 32) {
        if (strcmp(token, ".") == 0) {
            /* skip current dir reference */
        } else if (strcmp(token, "..") == 0) {
            /* go up one level */
            if (out->num_segments > 0) {
                out->num_segments--;
            }
        } else {
            strncpy(out->segments[out->num_segments], token, 255);
            out->segments[out->num_segments][255] = '\0';
            out->num_segments++;
        }
        token = strtok(NULL, "/");
    }
    return 0;
}

/* Reconstruct path from normalized segments */
static int build_resolved_path(const NormalizedPath *np, char *out, size_t out_sz) {
    out[0] = '\0';
    for (int i = 0; i < np->num_segments; i++) {
        if (i > 0) strncat(out, "/", out_sz - strlen(out) - 1);
        strncat(out, np->segments[i], out_sz - strlen(out) - 1);
    }
    return 0;
}

/* URL-decode a path component (handles %XX encoding) */
static void url_decode(const char *src, char *dst, size_t dst_sz) {
    size_t j = 0;
    for (size_t i = 0; src[i] && j < dst_sz - 1; i++) {
        if (src[i] == '%' && src[i+1] && src[i+2]) {
            char hex[3] = { src[i+1], src[i+2], '\0' };
            dst[j++] = (char)strtol(hex, NULL, 16);
            i += 2;
        } else {
            dst[j++] = src[i];
        }
    }
    dst[j] = '\0';
}

/* Validate that resolved path stays within bucket boundary using realpath */
static int validate_bucket_containment(const char *expected_prefix, const char *full_path) {
    char resolved[PATH_MAX];
    /* Resolve to canonical absolute path */
    /* For the directory portion, check it exists or use the path as-is */
    char dir_copy[MAX_PATH_LEN];
    strncpy(dir_copy, full_path, sizeof(dir_copy) - 1);
    dir_copy[sizeof(dir_copy) - 1] = '\0';

    /* Check that no segment after URL decoding contains traversal */
    if (strstr(full_path, "..") != NULL) {
        return -1;
    }

    /* Verify prefix match on the constructed path */
    if (strncmp(full_path, expected_prefix, strlen(expected_prefix)) != 0) {
        return -1;
    }
    return 0;
}

/* Encrypt data using AES-256-CBC */
static int encrypt_object_data(const StorageContext *ctx, const unsigned char *plaintext,
                               size_t pt_len, unsigned char **ciphertext, size_t *ct_len) {
    unsigned char iv[AES_IV_SIZE];
    if (RAND_bytes(iv, AES_IV_SIZE) != 1) {
        return -1;
    }

    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    *ciphertext = malloc(pt_len + BLOCK_SIZE + AES_IV_SIZE);
    if (!*ciphertext) { EVP_CIPHER_CTX_free(cipher_ctx); return -1; }

    memcpy(*ciphertext, iv, AES_IV_SIZE);

    int len = 0, total = 0;
    if (EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_cbc(), NULL, ctx->master_key, iv) != 1) {
        free(*ciphertext);
        *ciphertext = NULL;
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    if (EVP_EncryptUpdate(cipher_ctx, *ciphertext + AES_IV_SIZE, &len, plaintext, pt_len) != 1) {
        free(*ciphertext);
        *ciphertext = NULL;
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    total += len;
    if (EVP_EncryptFinal_ex(cipher_ctx, *ciphertext + AES_IV_SIZE + total, &len) != 1) {
        free(*ciphertext);
        *ciphertext = NULL;
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    total += len;

    *ct_len = AES_IV_SIZE + total;
    EVP_CIPHER_CTX_free(cipher_ctx);
    return 0;
}

/* Safe directory creation without shell injection */
static int create_parent_dirs(const char *path) {
    char tmp[MAX_PATH_LEN];
    strncpy(tmp, path, sizeof(tmp) - 1);
    tmp[sizeof(tmp) - 1] = '\0';

    for (char *p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            mkdir(tmp, 0750);
            *p = '/';
        }
    }
    mkdir(tmp, 0750);
    return 0;
}

/*
 * cloud_storage_put_object - Store an encrypted object in the bucket.
 * 
 * The object_key is URL-decoded, then path-normalized to prevent traversal.
 * After normalization, containment is validated before writing.
 */
int cloud_storage_put_object(StorageContext *ctx, const char *object_key,
                             const unsigned char *data, size_t data_len) {
    char decoded_key[MAX_PATH_LEN];
    char full_path[MAX_PATH_LEN];
    NormalizedPath np;
    char resolved_object[MAX_PATH_LEN];

    /* Step 1: URL-decode the object key */
    url_decode(object_key, decoded_key, sizeof(decoded_key));

    /* Step 2: Normalize path to eliminate traversal sequences */
    normalize_path_segments(decoded_key, &np);
    build_resolved_path(&np, resolved_object, sizeof(resolved_object));

    /* Step 3: Build full filesystem path using NORMALIZED path */
    snprintf(full_path, sizeof(full_path), "%s%s/%s",
             BUCKET_ROOT, ctx->bucket_id, resolved_object);

    /* Step 4: Validate containment on the FULL constructed path */
    if (validate_bucket_containment(BUCKET_ROOT, full_path) != 0) {
        fprintf(stderr, "Security: path traversal attempt blocked\n");
        return -1;
    }

    /* Step 5: Encrypt and write */
    unsigned char *ciphertext = NULL;
    size_t ct_len = 0;

    if (ctx->encryption_enabled) {
        if (encrypt_object_data(ctx, data, data_len, &ciphertext, &ct_len) != 0) {
            return -1;
        }
    } else {
        ciphertext = (unsigned char *)data;
        ct_len = data_len;
    }

    FILE *fp = fopen(full_path, "wb");
    if (!fp) {
        /* Try creating parent directories safely */
        char dir_path[MAX_PATH_LEN];
        strncpy(dir_path, full_path, sizeof(dir_path) - 1);
        dir_path[sizeof(dir_path) - 1] = '\0';
        char *last_slash = strrchr(dir_path, '/');
        if (last_slash) {
            *last_slash = '\0';
            create_parent_dirs(dir_path);
        }
        fp = fopen(full_path, "wb");
        if (!fp) {
            if (ctx->encryption_enabled) free(ciphertext);
            return -1;
        }
    }

    fwrite(ciphertext, 1, ct_len, fp);
    fclose(fp);

    if (ctx->encryption_enabled) free(ciphertext);
    return 0;
}
